import struct,gzip,base64
from pathlib import Path
import numpy as np
root=Path(__file__).parent

def pack(fn):
 b=(root/fn).read_bytes();nv,nt,nb=struct.unpack_from('<III',b);o=28
 v=np.frombuffer(b,dtype='<f4',count=nv*12,offset=o).copy().reshape(-1,12);o+=nv*48
 v[:,:3]=np.round(v[:,:3]*32)/32;v[:,3:7]=np.round(v[:,3:7]*1024)/1024;v[:,9:]=np.round(v[:,9:]*128)/128
 tex=np.frombuffer(b,dtype=np.uint8,count=nt*256*256*4,offset=o).reshape(nt,256,256,4);o+=tex.size;tex=tex[:,::4,::4].copy()
 light=np.frombuffer(b,dtype=np.uint8,count=4096*4096*4,offset=o).reshape(4096,4096,4);o+=light.size
 return base64.b64encode(gzip.compress(b[:28]+v.tobytes()+tex.tobytes()+light[::4,::4].tobytes()+b[o:],9)).decode()
