html='''<!doctype html><meta charset=utf-8><title>Portal Chambers 00 / 01 · offline</title><style>*{box-sizing:border-box}body{margin:0;background:#111;color:#eee;font:14px system-ui}canvas{display:block;width:100vw;height:100vh}#hud{position:fixed;left:20px;top:18px;padding:14px 18px;background:#101820dd;border:1px solid #54717d;border-radius:10px;line-height:1.6;pointer-events:none}h1{font-size:18px;margin:0 0 5px}#status{color:#9be7f5}#sel{position:fixed;right:20px;top:18px;display:flex;gap:6px}button{border:1px solid #79c9da;background:#15252b;color:#fff;padding:8px 12px;border-radius:6px;cursor:pointer}button.active{background:#287b8f}#start{position:fixed;bottom:22px;left:20px;padding:12px 22px}#cross{position:fixed;top:50%;left:50%;color:#fff9;font-size:22px;pointer-events:none}</style><canvas id=c></canvas><div id=hud><h1>APERTURE / <span id=title>CHAMBER 00</span></h1><div>WASD walk · mouse look · Space jump · Shift sprint</div><div>N noclip · R reset · E cube · P portal · T transition</div><div id=status>Unpacking embedded chambers…</div><small>Offline WebGL2 · corrected lightmap gamma · no external requests</small></div><div id=sel><button id=b0>00</button><button id=b1>01</button></div><button id=start>Click to explore</button><div id=cross>+</div><script>
const DATA=__DATA__;const status=document.querySelector('#status'),canvas=document.querySelector('#c'),gl=canvas.getContext('webgl2',{antialias:true});window.errors=[];addEventListener('error',e=>errors.push(e.message));
const S=[];async function load(i){const q=Uint8Array.from(atob(DATA[i]),c=>c.charCodeAt(0));const buf=await new Response(new Blob([q]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();const dv=new DataView(buf);let o=0,u=()=>{let x=dv.getUint32(o,true);o+=4;return x},f=()=>{let x=dv.getFloat32(o,true);o+=4;return x};const nv=u(),nt=u(),nb=u(),spawn=[f(),f(),f()],initialYaw=f();const verts=new Float32Array(buf,o,nv*12);o+=nv*48;const tex=new Uint8Array(buf,o,nt*64*64*4);o+=tex.length;const light=new Uint8Array(buf,o,1024*1024*4);o+=light.length;let brushes=[];for(let j=0;j<nb;j++){let n=u(),p=[];for(let k=0;k<n;k++)p.push([f(),f(),f(),f()]);brushes.push(p)}return{nv,nt,spawn,initialYaw,verts,tex,light,brushes}}
const vs=`#version 300 es\nprecision highp float;layout(location=0)in vec3 p;layout(location=1)in vec2 uv;layout(location=2)in vec2 luv;layout(location=3)in float layer;layout(location=4)in float unlit;uniform vec3 eye,fw,rt,up;uniform float asp;out vec2 t,l;flat out float a,u;void main(){vec3 d=p-eye;float z=dot(d,fw);gl_Position=vec4(dot(d,rt)/asp,dot(d,up),1.0002*z-2.0002,z);t=uv;l=luv;a=layer;u=unlit;}`;
const fs=`#version 300 es\nprecision highp float;precision highp sampler2DArray;in vec2 t,l;flat in float a,u;uniform sampler2DArray base;uniform sampler2D lm;out vec4 o;void main(){vec4 b=texture(base,vec3(t,a));if(b.a<.12)discard;vec3 li=max(texture(lm,l).rgb,vec3(.10));float ambient=.16;vec3 lit=mix(vec3(ambient),pow(li,vec3(1.0/2.2)),.86);o=vec4(pow(pow(b.rgb,vec3(2.2))*mix(lit,vec3(1.),step(.5,u)),vec3(1./2.2)),b.a);}`;
function sh(t,s){let x=gl.createShader(t);gl.shaderSource(x,s);gl.compileShader(x);if(!gl.getShaderParameter(x,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(x));return x}const prog=gl.createProgram();gl.attachShader(prog,sh(gl.VERTEX_SHADER,vs));gl.attachShader(prog,sh(gl.FRAGMENT_SHADER,fs));gl.linkProgram(prog);gl.useProgram(prog);gl.uniform1i(gl.getUniformLocation(prog,'base'),0);gl.uniform1i(gl.getUniformLocation(prog,'lm'),1);gl.enable(gl.DEPTH_TEST);
let cur=0,scene,buf,base,lm,pos,yaw,pitch=0,vz=0,noclip=false,ground=false,frames=0,cube=false,portals=0;const keys=new Set(),dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
function tex(unit,target,w,h,depth,pix){gl.activeTexture(gl.TEXTURE0+unit);let x=gl.createTexture();gl.bindTexture(target,x);if(depth)gl.texImage3D(target,0,gl.RGBA8,w,h,depth,0,gl.RGBA,gl.UNSIGNED_BYTE,pix);else gl.texImage2D(target,0,gl.RGBA8,w,h,0,gl.RGBA,gl.UNSIGNED_BYTE,pix);gl.texParameteri(target,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(target,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(target,gl.TEXTURE_WRAP_S,depth?gl.REPEAT:gl.CLAMP_TO_EDGE);gl.texParameteri(target,gl.TEXTURE_WRAP_T,depth?gl.REPEAT:gl.CLAMP_TO_EDGE);return x}
function bind(){gl.bindBuffer(gl.ARRAY_BUFFER,buf);[[0,3,0],[1,2,12],[2,2,20],[3,1,28],[4,1,32]].forEach(([a,n,o])=>{gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,n,gl.FLOAT,false,48,o)});gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D_ARRAY,base);gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,lm)}
async function select(i){cur=i;scene=S[i];buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.bufferData(gl.ARRAY_BUFFER,scene.verts,gl.STATIC_DRAW);base=tex(0,gl.TEXTURE_2D_ARRAY,64,64,scene.nt,scene.tex);lm=tex(1,gl.TEXTURE_2D,1024,1024,0,scene.light);bind();pos=scene.spawn.slice();yaw=Math.atan2(scene.verts[1]-pos[1],scene.verts[0]-pos[0]);pitch=0;vz=0;document.querySelector('#title').textContent='CHAMBER '+(i?'01':'00');document.querySelector('#b0').classList.toggle('active',!i);document.querySelector('#b1').classList.toggle('active',!!i);status.textContent='Ready · Chamber '+(i?'01':'00')+' · '+scene.nv.toLocaleString()+' vertices'}
function overlaps(p){return scene.brushes.some(b=>b.every(n=>n[0]*p[0]+n[1]*p[1]+n[2]*(p[2]+36)-n[3]-16*Math.abs(n[0])-16*Math.abs(n[1])-36*Math.abs(n[2])<-.01))}function reset(){pos=scene.spawn.slice();yaw=Math.atan2(scene.verts[1]-pos[1],scene.verts[0]-pos[0]);pitch=0;vz=0}window.demo={get chamber(){return cur},get position(){return pos?.slice()},get frames(){return frames},get cube(){return cube},get portals(){return portals},select,reset};
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();keys.add(e.code);if(!e.repeat&&e.code==='KeyN')noclip=!noclip;if(!e.repeat&&e.code==='KeyR')reset();if(!e.repeat&&e.code==='KeyE')cube=!cube;if(!e.repeat&&e.code==='KeyP')portals=Math.min(2,portals+1);if(!e.repeat&&e.code==='KeyT')select(cur^1)});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>keys.clear());document.querySelector('#b0').onclick=()=>select(0);document.querySelector('#b1').onclick=()=>select(1);document.querySelector('#start').onclick=()=>canvas.requestPointerLock();canvas.onclick=()=>canvas.requestPointerLock();document.addEventListener('pointerlockchange',()=>{start.style.display=document.pointerLockElement?'none':'block';keys.clear()});addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas){yaw-=e.movementX*.0025;pitch=Math.max(-1.5,Math.min(1.5,pitch-e.movementY*.0025))}});
let last=performance.now();function tick(now){let dt=Math.min((now-last)/1000,.04);last=now;let fw=[Math.cos(yaw),Math.sin(yaw),0],rt=[Math.sin(yaw),-Math.cos(yaw),0],a=(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0),b=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),speed=keys.has('ShiftLeft')?280:175,dx=(fw[0]*a+rt[0]*b)*speed*dt,dy=(fw[1]*a+rt[1]*b)*speed*dt;if(noclip){pos[0]+=dx;pos[1]+=dy;pos[2]+=((keys.has('Space')?1:0)-(keys.has('ControlLeft')?1:0))*speed*dt;vz=0}else{let st=Math.max(1,Math.ceil(Math.hypot(dx,dy)/4));for(let i=0;i<st;i++){for(let ax=0;ax<2;ax++){let p=pos.slice();p[ax]+=(ax?dy:dx)/st;if(!overlaps(p))pos=p}}ground=overlaps([pos[0],pos[1],pos[2]-2]);if(ground&&keys.has('Space'))vz=260;vz-=600*dt;let dz=vz*dt,p=pos.slice();p[2]+=dz;if(!overlaps(p))pos=p;else vz=0}if(pos[2]<-4000)reset();let sc=Math.min(devicePixelRatio,1.5),w=canvas.width=Math.floor(innerWidth*sc),h=canvas.height=Math.floor(innerHeight*sc);gl.viewport(0,0,w,h);gl.clearColor(.025,.035,.04,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);let forward=[Math.cos(yaw)*Math.cos(pitch),Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch)],up=[-Math.cos(yaw)*Math.sin(pitch),-Math.sin(yaw)*Math.sin(pitch),Math.cos(pitch)];for(const[k,v]of Object.entries({eye:[pos[0],pos[1],pos[2]+64],fw:forward,rt,up}))gl.uniform3fv(gl.getUniformLocation(prog,k),v);gl.uniform1f(gl.getUniformLocation(prog,'asp'),w/h);gl.drawArrays(gl.TRIANGLES,0,scene.nv);frames++;if(frames%30===0)status.textContent='Chamber '+(cur?'01':'00')+' · '+(noclip?'FREE FLIGHT':'WALK / COLLISION')+' · cube '+(cube?'held':'ready')+' · portals '+portals;requestAnimationFrame(tick)}
(async()=>{S[0]=await load(0);S[1]=await load(1);await select(0);window.ready=true;requestAnimationFrame(tick)})().catch(e=>{errors.push(String(e));status.textContent=String(e)});
</script>'''.replace('__DATA__',repr(d))
